"use strict";(self.webpackChunktemp_docusaurus=self.webpackChunktemp_docusaurus||[]).push([["266"],{6164(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/practica-1","label":"Pr\xe1ctica 1: Aspiradora de baja gama","docId":"practica-1","unlisted":false},{"type":"link","href":"/docs/practica-2","label":"Pr\xe1ctica 2: Control Control Visual con PID de un F\xf3rmula1","docId":"practica-2","unlisted":false},{"type":"link","href":"/docs/practica-3","label":"Practica 3: Navegaci\xf3n local esquivando obst\xe1culos con algoritmo VFF","docId":"practica-3","unlisted":false}]},"docs":{"practica-1":{"id":"practica-1","title":"Pr\xe1ctica 1: Aspiradora de baja gama","description":"El software de la aspiradora est\xe1 compuesto de cuatro estados. El primer estado es el SPIRAL, sirve para limpiar el m\xe1ximo posible al comienzo de la simulaci\xf3n. Cuando el robot detecta con el laser un obst\xe1culo a menos de 0,4 metros se detiene y entra el segundo estado SPINNING. El robot gira sobre si mismo durante un tiempo aleatorio entre 1 y 2 segundos para dar que sea una navegaci\xf3n pseudoaleatoria tal y como pide la pr\xe1ctica. El \xfaltimo estado es FORWARD. El robot avanza en linea recta hasta que el laser lee un obst\xe1culo y vuelve al segundo estado. De esta manera que sea un bucle infinito como pide la pr\xe1ctica.","sidebar":"tutorialSidebar"},"practica-2":{"id":"practica-2","title":"Pr\xe1ctica 2: Control Control Visual con PID de un F\xf3rmula1","description":"El objetivo del control visual es que el robot vea donde est\xe1 la l\xednea roja respecto a su propio centro.","sidebar":"tutorialSidebar"},"practica-3":{"id":"practica-3","title":"Practica 3: Navegaci\xf3n local esquivando obst\xe1culos con algoritmo VFF","description":"Implementar la l\xf3gica de navegaci\xf3n local con el algoritmo Virtual Force Field (VFF) para un coche equipado con un l\xe1ser de 180 rayos. El destino genera una fuerza de atracci\xf3n y los obst\xe1culos una fuerza de repulsi\xf3n, de modo que la direcci\xf3n del robot se obtiene a partir de la combinaci\xf3n de ambas. El robot debe recorrer el circuito pasando por una serie de waypoints sin chocar.","sidebar":"tutorialSidebar"}}}}')}}]);